package com.bank.channel.service;

import com.bank.channel.dto.ChannelResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Slf4j
public class ChannelReconService {

    public ChannelResult findFirstUnreconciled(List<String> channels) {

        Map<String, Long> freq = channels.stream()
            .collect(Collectors.groupingBy(Function.identity(),
                LinkedHashMap::new, Collectors.counting()));

        Optional<String> firstNonRepeating = freq.entrySet().stream()
            .filter(e -> e.getValue() == 1L)
            .map(Map.Entry::getKey)
            .findFirst();

        log.info("Channels: {} | First non-repeating: {}", freq, firstNonRepeating.orElse("none"));

        return new ChannelResult(channels, firstNonRepeating.orElse(null), freq);
    }
}
