package com.bank.channel.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class FirstNonRepeatingStringTest {

    private Optional<String> findFirst(List<String> list) {
        return list.stream()
            .collect(Collectors.groupingBy(Function.identity(),
                LinkedHashMap::new, Collectors.counting()))
            .entrySet().stream()
            .filter(e -> e.getValue() == 1L)
            .map(Map.Entry::getKey)
            .findFirst();
    }

    @Test
    void basicCase() {
        assertThat(findFirst(List.of("NEFT", "UPI", "NEFT", "RTGS", "UPI", "IMPS")))
            .contains("RTGS");  // NEFT=2, UPI=2, RTGS=1, IMPS=1 → RTGS first
    }

    @Test
    void allRepeating() {
        assertThat(findFirst(List.of("NEFT", "UPI", "NEFT", "UPI"))).isEmpty();
    }

    @Test
    void allUnique() {
        assertThat(findFirst(List.of("NEFT", "UPI", "RTGS"))).contains("NEFT");
    }

    @Test
    void singleElement() {
        assertThat(findFirst(List.of("IMPS"))).contains("IMPS");
    }

    @Test
    void caseSensitive() {
        assertThat(findFirst(List.of("neft", "NEFT", "neft"))).contains("NEFT");
        // "neft"=2, "NEFT"=1 → NEFT is first non-repeating
    }
}
